// Минимальный клиент для нативного приложения Eitan на реальном Android по кабелю: только adb (без Appium, без зависимостей, Node 22).
// Экран читается через `uiautomator dump`, касания — `input tap` по центру bounds. Серийник — из переменной BANCI_ANDROID_SERIAL (личное значение, см. ~/.qa-tester/devices.md).
import { execFile } from 'node:child_process';
import { writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
export const ANDROID_PACKAGE = process.env.BANCI_ANDROID_PACKAGE || 'com.eitan.poolsafety';
const SERIAL = process.env.BANCI_ANDROID_SERIAL;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms)); // интервал опроса, не ожидание результата

export function assert(cond, message) {
  if (!cond) throw new Error(`Проверка не прошла: ${message}`);
}
/** Пропустить тест с понятной причиной (ручное предусловие). run-android.mjs считает его «skipped». */
export function skip(reason) {
  const e = new Error(`ПРОПУЩЕН: ${reason}`);
  e.skip = true;
  throw e;
}

function adb(args, { timeout = 30000 } = {}) {
  if (!SERIAL) throw new Error('Нет переменной BANCI_ANDROID_SERIAL — серийник из ~/.qa-tester/devices.md (adb devices), см. README.md');
  return new Promise((resolve, reject) => {
    execFile('adb', ['-s', SERIAL, ...args], { timeout, maxBuffer: 16 * 1024 * 1024, encoding: 'utf8' }, (err, stdout, stderr) => {
      if (err) reject(new Error(`adb ${args.join(' ')} → ${(stderr || err.message).trim().split('\n')[0]}`));
      else resolve(stdout);
    });
  });
}
export const sh = (cmd, opts) => adb(['shell', cmd], opts);

const decode = (s) => s.replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#10;/g, '\n').replace(/&amp;/g, '&');

/** Дамп UI → плоский список узлов с родителями. */
function parseDump(xml) {
  const nodes = [];
  const stack = [];
  const re = /<node\b([^>]*?)(\/?)>|<\/node>/g;
  let m;
  while ((m = re.exec(xml))) {
    if (m[0] === '</node>') { stack.pop(); continue; }
    const attrs = {};
    for (const a of m[1].matchAll(/([\w-]+)="([^"]*)"/g)) attrs[a[1]] = decode(a[2]);
    const b = /\[(\d+),(\d+)\]\[(\d+),(\d+)\]/.exec(attrs.bounds || '');
    const node = {
      text: attrs.text || '', checked: attrs.checked === 'true', desc: attrs['content-desc'] || '', enabled: attrs.enabled !== 'false', clickable: attrs.clickable === 'true',
      cx: b ? (+b[1] + +b[3]) / 2 : 0, cy: b ? (+b[2] + +b[4]) / 2 : 0, w: b ? +b[3] - +b[1] : 0, parent: stack[stack.length - 1] || null,
    };
    nodes.push(node);
    if (m[2] !== '/') stack.push(node);
  }
  return nodes;
}

export class Android {
  static async start() {
    const out = await adb(['get-state']);
    if (!out.trim().startsWith('device')) throw new Error('Android не подключён (adb get-state ≠ device): кабель, разблокировать экран');
    return new Android();
  }

  /** Перезапуск приложения: данные и вход не трогаем. */
  async restart() {
    await sh(`am force-stop ${ANDROID_PACKAGE}`);
    await sh(`monkey -p ${ANDROID_PACKAGE} -c android.intent.category.LAUNCHER 1`);
  }

  async dump() {
    const xml = await sh('uiautomator dump /dev/tty', { timeout: 40000 });
    return parseDump(xml.slice(xml.indexOf('<?xml')));
  }

  /** Узлы, у которых text или content-desc содержит/равен тексту. */
  async findAll(text, { exact = false } = {}) {
    const nodes = await this.dump();
    return nodes.filter((n) => [n.text, n.desc].some((v) => v && (exact ? v.trim() === text : v.includes(text))));
  }

  async waitFor(text, { timeout = 15000, exact = false, what } = {}) {
    const end = Date.now() + timeout;
    let last;
    while (Date.now() < end) {
      try { const els = await this.findAll(text, { exact }); if (els.length) return els[0]; } catch (e) { last = e; }
      await sleep(500);
    }
    throw new Error(`Не найден за ${timeout} мс: ${what || text}${last ? ` (${last.message})` : ''}`);
  }

  async waitGone(text, { timeout = 10000, what } = {}) {
    const end = Date.now() + timeout;
    while (Date.now() < end) {
      if (!(await this.findAll(text)).length) return;
      await sleep(500);
    }
    throw new Error(`Не исчез за ${timeout} мс: ${what || text}`);
  }

  async exists(text, opts) { return (await this.findAll(text, opts)).length > 0; }

  tapNode(n) { return sh(`input tap ${Math.round(n.cx)} ${Math.round(n.cy)}`); }
  async tap(text, opts) { const n = await this.waitFor(text, opts); await this.tapNode(n); return n; }

  /** enabled кнопки: сам узел или ближайший clickable-предок (в RN текст — дочерний узел кнопки). */
  static isEnabled(n) {
    let cur = n;
    while (cur) { if (cur.clickable) return cur.enabled; cur = cur.parent; }
    return n.enabled;
  }
  /** checked чекбокса: сам узел или ближайший clickable-предок (в RN checked стоит на кнопке-обёртке). */
  static isChecked(n) {
    let cur = n;
    while (cur) { if (cur.clickable) return cur.checked; cur = cur.parent; }
    return n.checked;
  }
  /** Ждёт, пока чекбокс станет checked === want (опрос результата). */
  async waitChecked(text, want, { timeout = 5000, what = text } = {}) {
    const end = Date.now() + timeout;
    let s;
    while (Date.now() < end) {
      const els = await this.findAll(text);
      if (els.length) { s = Android.isChecked(els[0]); if (s === want) return; }
      await sleep(400);
    }
    throw new Error(`Проверка не прошла: ${what} — ожидалось ${want ? 'отмечена' : 'не отмечена'}, сейчас ${s === undefined ? 'не найдена' : s ? 'отмечена' : 'не отмечена'}`);
  }

  /** Свайп вверх по заголовку (превью камеры перехватывает жест) — пока элемент не появится на экране. */
  async scrollTo(text, { max = 4, from = 'כוונו את המצלמה לבריכה', what = text } = {}) {
    for (let i = 0; i <= max; i++) {
      const els = await this.findAll(text);
      if (els.length) return els[0];
      const h = (await this.findAll(from))[0];
      const size = /(\d+)x(\d+)/.exec(await sh('wm size'));
      const H = size ? +size[2] : 2400;
      const x = h ? Math.round(h.cx) : 540, y = h ? Math.round(h.cy) : Math.round(H * 0.2);
      await sh(`input swipe ${x} ${y} ${x} ${Math.max(10, y - Math.round(H * 0.4))} 400`);
    }
    throw new Error(`Не найден после ${max} свайпов вверх: ${what}`);
  }

  /** Ждёт, пока кнопка станет enabled === want (опрос результата). */
  async waitEnabled(text, want, { timeout = 15000, what = text, exact = true } = {}) {
    const end = Date.now() + timeout;
    let s;
    while (Date.now() < end) {
      const els = await this.findAll(text, { exact });
      if (els.length) { s = Android.isEnabled(els[0]); if (s === want) return; }
      await sleep(500);
    }
    throw new Error(`Проверка не прошла: ${what} — ожидалось ${want ? 'активна' : 'неактивна (серая)'}, сейчас ${s ? 'активна' : s === undefined ? 'не найдена' : 'неактивна'}`);
  }

  async screenshot(name) {
    const dir = path.join(ROOT, 'results');
    await mkdir(dir, { recursive: true });
    const file = path.join(dir, `${new Date().toISOString().slice(0, 10)}-android-${name}.png`);
    const png = await new Promise((resolve, reject) => {
      execFile('adb', ['-s', SERIAL, 'exec-out', 'screencap', '-p'], { encoding: 'buffer', maxBuffer: 32 * 1024 * 1024 }, (e, out) => (e ? reject(e) : resolve(out)));
    });
    await writeFile(file, png);
    return file;
  }

  // ── Звук телефона (меняется по adb, после теста возвращается) ──
  async getRingerMode() { return Number((await sh('settings get global mode_ringer')).trim()); } // 0 беззвучный, 1 вибрация, 2 звонок
  setRingerMode(mode) { return sh(`cmd audio set-ringer-mode ${mode}`); } // NORMAL | VIBRATE | SILENT
  /** Громкость медиа 0..max. `cmd media_session volume --set` НЕ работает — только `cmd audio set-volume 3 N` (3 = STREAM_MUSIC). */
  setMediaVolume(n) { return sh(`cmd audio set-volume 3 ${n}`); }
  async mediaMax() {
    const v = Number((await sh('cmd audio get-max-volume 3').catch(() => '')).trim());
    return Number.isFinite(v) && v > 0 ? v : 25; // Pixel 6: 25
  }
  async mediaVolume() {
    const v = Number((await sh('cmd audio get-volume 3').catch(() => '')).trim());
    return Number.isFinite(v) ? v : null;
  }
}

/** Шаг 1 «בדיקת בטיחות» (без прохождения): בית → «התחלת ניטור» → ждём «N מתוך 5». Мониторинг НЕ запускается. */
export async function openSafetyCheck(app) {
  await app.restart();
  await app.waitFor('בית', { timeout: 30000, what: 'главный экран «בית» (приложение не залогинено? войти вручную)' });
  await app.tap('התחלת ניטור', { timeout: 20000, what: '«התחלת ניטור» на בית' });
  await app.waitFor('בדיקת בטיחות', { timeout: 20000, what: 'экран «בדיקת בטיחות»' });
  return app.waitFor('מתוך 5', { timeout: 30000, what: 'счётчик «N מתוך 5»' });
}

/**
 * Выставить режим звонка и громкость медиа на время теста; в конце — вернуть как было.
 * mode: NORMAL | VIBRATE | SILENT; media: число или 'max'.
 */
export async function withAudio(app, { mode, media }, fn) {
  const prevMode = await app.getRingerMode();
  const prevMedia = await app.mediaVolume();
  const max = await app.mediaMax();
  try {
    await app.setRingerMode(mode);
    await app.setMediaVolume(media === 'max' ? max : media);
    return await fn({ max });
  } finally {
    // Возврат: режим звонка как был, медиа как было (не прочитали — максимум, как нужно остальным тестам и тревогам).
    await app.setRingerMode(['SILENT', 'VIBRATE', 'NORMAL'][[0, 1, 2].indexOf(prevMode)] || 'NORMAL').catch(() => {});
    await app.setMediaVolume(prevMedia ?? max).catch(() => {});
  }
}

export const WATER_CHECKBOX = 'כל שטח המים נראה';
export const NO_WATER_HINT = 'לא זוהו מים באזור שסומן';
export const OLD_POOL_CHECKBOX = 'זו הבריכה שלי';
export const PALE_HINT = 'בהירים מהרגיל';

/**
 * «בית» → «התחלת ניטור» → «בדיקת בטיחות» (5 מתוך 5) → «המשך» → шаг 2 «כוונו את המצלמה לבריכה».
 * Если на шаге 1 просят тестовый звук — он ГРОМКИЙ: без BANCI_SOUND=1 тест пропускается (как 1.48). Мониторинг НЕ запускается.
 * Возвращает узел чекбокса «כל שטח המים נראה בתמונה…» (ниже края — прокручивается свайпом по заголовку).
 */
export async function openCameraStep(app) {
  await openSafetyCheck(app);
  if (await app.exists('השמיעו את צליל הבדיקה ואשרו ששמעתם אותו')) {
    if (process.env.BANCI_SOUND !== '1') skip('шаг 1 просит тестовый звук (ГРОМКИЙ): рядом никого нет → запустить с BANCI_SOUND=1, либо вручную пройти «בדיקת בטיחות» до 5/5 (звонок + громкость медиа в норме)');
    await app.tapNode(await app.waitFor('השמיעו את צליל הבדיקה ואשרו ששמעתם אותו', { what: 'строка «השמיעו את צליל הבדיקה…»' }));
    await app.waitFor('בדיקת צליל ההתרעה', { timeout: 10000, what: 'лист «בדיקת צליל ההתרעה»' });
    await app.tap('השמעה', { exact: true, what: '«השמעה» (единственный звук)' });
    await app.tap('שמעתי', { exact: true, what: '«שמעתי»' });
    await app.waitGone('בדיקת צליל ההתרעה', { what: 'лист закрылся' });
  }
  await app.waitFor('5 מתוך 5', { timeout: 20000, what: '«5 מתוך 5» (ПРЕДУСЛОВИЕ: батарея > 30% или зарядка, разрешения, второй телефон)' });
  await app.waitEnabled('המשך', true, { what: '«המשך» на «בדיקת בטיחות»' });
  await app.tap('המשך', { exact: true, what: '«המשך» на шаге 1' });
  await app.waitFor('כוונו את המצלמה לבריכה', { timeout: 20000, what: 'заголовок шага 2 «כוונו את המצלמה לבריכה»' });
  return app.scrollTo(WATER_CHECKBOX, { what: 'чекбокс «כל שטח המים נראה בתמונה…»' });
}

/** Поставить галочку «כל שטח המים נראה בתמונה…» (если ещё нет) и дождаться отметки. */
export async function checkWaterBox(app) {
  const el = await app.scrollTo(WATER_CHECKBOX, { what: 'чекбокс «כל שטח המים נראה…»' });
  if (!Android.isChecked(el)) await app.tapNode(el);
  await app.waitChecked(WATER_CHECKBOX, true, { what: 'галочка «כל שטח המים נראה בתמונה…»' });
}
